.wf-detail{--wf-accent:var(--wf-color-primary,#12b8a6);--wf-panel:var(--wf-color-surface,#fff);--wf-border:var(--wf-color-border,#dbe4ea);--wf-text:var(--wf-color-text,#102230);--wf-muted:var(--wf-color-muted,#647482);box-sizing:border-box;max-width:1100px;margin:0 auto;padding:clamp(1rem,3vw,2.5rem);color:var(--wf-text);font-family:Inter,system-ui,sans-serif}.wf-detail *{box-sizing:border-box}.wf-detail__back{display:inline-flex;margin:.25rem 0 1rem;color:var(--wf-accent);font-weight:750;text-decoration:none}.wf-detail__status{margin:0 0 1rem;color:var(--wf-muted)}.wf-detail__status[data-error=true]{padding:.75rem;border-radius:.65rem;background:#fff2f2;color:#a12626}.wf-detail__layout{display:grid;grid-template-columns:minmax(16rem,1.1fr) minmax(16rem,.9fr);gap:1.5rem}.wf-detail__gallery{display:grid;gap:.75rem;align-content:start}.wf-detail__image{width:100%;aspect-ratio:4/3;object-fit:contain;background:var(--wf-color-secondary,#f1f4f6);border:1px solid var(--wf-border);border-radius:1rem}.wf-detail__thumbs{display:flex;flex-wrap:wrap;gap:.5rem}.wf-detail__thumb{width:4.5rem;height:4.5rem;padding:.2rem;border:1px solid var(--wf-border);border-radius:.7rem;background:var(--wf-panel);cursor:pointer}.wf-detail__thumb[aria-current=true]{border-color:var(--wf-accent);box-shadow:0 0 0 2px var(--wf-border)}.wf-detail__thumb img{width:100%;height:100%;object-fit:contain}.wf-detail__meta{margin:0 0 .35rem;color:var(--wf-muted);font-size:.77rem;letter-spacing:.05em;text-transform:uppercase}.wf-detail h1{margin:0;font-size:clamp(1.6rem,3vw,2.4rem);line-height:1.15}.wf-detail__price{margin:.8rem 0 0;font-size:1.35rem;font-weight:850}.wf-detail__stock{margin:.35rem 0 0;color:#197149;font-size:.9rem}.wf-detail__stock[data-empty=true]{color:#a63d3d}.wf-detail__description{margin-top:1rem;line-height:1.55;white-space:pre-wrap}.wf-detail__specs{margin-top:2rem}.wf-detail__specs h2{margin:0 0 .75rem;font-size:1.15rem}.wf-detail table{width:100%;border-collapse:collapse}.wf-detail th,.wf-detail td{padding:.7rem .2rem;border-bottom:1px solid var(--wf-border);text-align:left;vertical-align:top}.wf-detail th{width:38%;color:var(--wf-muted);font-weight:650}.wf-detail__link{color:inherit;font-weight:700;text-decoration:none}.wf-detail__link:hover{color:var(--wf-accent)}.wf-detail__related{margin-top:2.5rem}.wf-detail__related h2{margin:0 0 .75rem;font-size:1.15rem}.wf-detail__related-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.75rem}.wf-detail__card{display:flex;flex-direction:column;gap:.45rem;padding:.7rem;border:1px solid var(--wf-border);border-radius:1rem;background:var(--wf-panel);color:inherit;text-decoration:none}.wf-detail__card img{width:100%;aspect-ratio:4/3;object-fit:contain;background:var(--wf-color-secondary,#f1f4f6);border-radius:.7rem}.wf-detail__card-body{display:flex;flex-direction:column;gap:.2rem}.wf-detail__card-brand{color:var(--wf-muted);font-size:.72rem;letter-spacing:.04em;text-transform:uppercase}.wf-detail__card strong{font-size:.95rem;line-height:1.3}@media(max-width:800px){.wf-detail__layout{grid-template-columns:1fr}.wf-detail__related-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
.wf-detail__regular-price{display:block;margin-top:.75rem;color:var(--wf-muted)}.wf-detail__discount{display:inline-block;color:var(--wf-text);font-weight:700}.wf-detail__offers-status{color:var(--wf-muted);font-size:.85rem}.wf-detail [hidden]{display:none!important}
.wf-detail [data-wf-stock]{display:block;min-height:1.5em}.wf-detail__prices{min-height:4.25rem}.wf-detail [data-wf-offers-status]:empty{display:none}.wf-detail__card-body{min-height:6.5rem}

.wf-stock__truck {width:18px;height:18px;vertical-align:middle;margin-right:5px;}
.wf-detail__stock {min-height:2.5em;}

.wf-detail__documents{margin-top:32px}.wf-detail__documents ul{list-style:none;padding:0;display:grid;gap:10px}.wf-detail__documents a{display:flex;align-items:center;gap:12px;padding:14px 16px;border:1px solid var(--wf-color-border);border-radius:8px;color:inherit;text-decoration:underline;overflow-wrap:anywhere}.wf-detail__documents a::before{content:"↓";font-size:22px}

.wf-shop,.wf-shop-actions,.wf-shop-shell,.wf-variants{--shop-accent:var(--wf-color-primary,#ff9800);--shop-text:var(--wf-color-text,#222526);--shop-muted:var(--wf-color-muted,#626a70);--shop-border:var(--wf-color-border,#e0e4e7);--shop-surface:var(--wf-color-surface,#fff);color:var(--shop-text);font-family:inherit;box-sizing:border-box}
.wf-shop *,.wf-shop-actions *,.wf-shop-shell *,.wf-variants *{box-sizing:border-box}
.wf-shop{max-width:1160px;padding:32px 24px 64px;margin:0 auto;min-height:45vh}
.wf-shop h1{font-size:clamp(26px,4vw,36px);line-height:1.15;margin:0 0 24px;font-weight:800;letter-spacing:-.025em}
.wf-shop h2{font-size:21px;margin:24px 0 16px}.wf-shop [hidden],.wf-shop-actions [hidden],.wf-shop-shell [hidden]{display:none!important}
.wf-shop-btn,.wf-shop-heart,.wf-shop-link{font:inherit;cursor:pointer;min-height:42px;border-radius:8px;transition:background-color .15s}
.wf-shop-btn{display:inline-flex;align-items:center;justify-content:center;padding:10px 17px;font-weight:750;text-decoration:none;background:var(--shop-accent);border:1px solid transparent;color:var(--wf-shop-on-accent,#171a1c);line-height:1.3}
.wf-shop-btn:hover{filter:brightness(.96)}.wf-shop-btn:disabled{background:#edf0f2;color:#778189;cursor:default;filter:none}.wf-shop-btn:focus-visible,.wf-shop-heart:focus-visible,.wf-shop input:focus-visible,.wf-shop select:focus-visible,.wf-shop-actions input:focus-visible{outline:2px solid var(--shop-accent);outline-offset:3px}
.wf-shop-link{border:0;background:transparent;color:var(--shop-muted);padding:6px 8px;text-decoration:underline;text-underline-offset:3px;font-size:13px}
.wf-shop-shell{display:flex;align-items:center;gap:5px}.wf-shop-shell a{display:inline-flex;align-items:center;gap:6px;padding:9px;color:inherit;text-decoration:none;border-radius:8px;min-height:42px;white-space:nowrap}.wf-shop-shell a:hover{background:var(--wf-color-secondary,#f4f5f6)}
.wf-shop-shell svg,.wf-shop-heart svg{width:21px;height:21px;flex:none}.wf-shop-shell [data-wf-cart-count],.wf-shop-shell [data-wf-favorite-count]{font-size:11px;line-height:18px;min-width:18px;text-align:center;background:var(--shop-text);color:var(--shop-surface);border-radius:9px;font-variant-numeric:tabular-nums}
.wf-shop-actions{padding:10px 12px 12px;border-top:1px solid var(--shop-border);min-height:65px}.wf-detail [data-wf-shop-actions]{padding:16px 0;margin-top:12px}.wf-shop-actions__row{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.wf-shop-actions .wf-shop-btn{flex:1;font-size:13px;padding:9px 10px;min-width:115px}.wf-shop-qty{width:62px;min-width:0;min-height:42px;border:1px solid var(--shop-border);border-radius:8px;background:var(--shop-surface);color:var(--shop-text);font:inherit;padding:8px 5px;text-align:center;font-variant-numeric:tabular-nums}.wf-shop-unit{font-size:12px;color:var(--shop-muted)}
.wf-shop-actions[data-wf-variants=true]{min-height:115px}.wf-product:has(.wf-shop-actions)>.wf-product__link{height:auto;flex:1}
.wf-product:has(.wf-shop-actions){position:relative}.wf-product .wf-shop-heart{position:absolute;top:10px;right:10px;z-index:2;box-shadow:0 1px 4px #0001}.wf-catalog[data-badge-position=top-end] .wf-product .wf-shop-heart{left:10px;right:auto}.wf-shop-actions .wf-shop-qty{width:56px}.wf-product .wf-shop-btn{min-width:105px;font-size:12px}.wf-shop-unit{white-space:nowrap}
.wf-shop-heart{display:inline-flex;align-items:center;justify-content:center;flex:none;width:42px;border:1px solid var(--shop-border);background:var(--shop-surface);color:var(--shop-muted)}.wf-shop-heart[aria-pressed=true]{color:#b52737;background:#fff5f6}.wf-shop-heart[aria-pressed=true] svg{fill:currentColor}
.wf-shop-variant{width:100%;margin-bottom:8px;padding:10px;border:1px solid var(--shop-border);border-radius:8px;font:inherit;background:var(--shop-surface);color:var(--shop-text)}
.wf-shop-lines{border-top:1px solid var(--shop-border);margin-bottom:24px}.wf-shop-line{display:flex;align-items:center;gap:18px;padding:20px 0;border-bottom:1px solid var(--shop-border);min-width:0}.wf-shop-line img{width:88px;height:88px;object-fit:cover;border-radius:10px;background:#f5f6f7}.wf-shop-line__body{display:flex;flex:1;flex-direction:column;gap:7px;min-width:0}.wf-shop-line a{color:var(--shop-text);font-weight:750;text-decoration:none}.wf-shop-line a:hover{text-decoration:underline}.wf-shop-line small{color:var(--shop-muted);font-size:12px}.wf-shop-line__controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}.wf-shop-line__controls strong{display:block;min-width:100px;text-align:right;font-variant-numeric:tabular-nums}.wf-shop-line__controls .wf-shop-qty{width:78px}
.wf-shop-totals{width:min(100%,370px);margin-left:auto;border-top:1px solid var(--shop-border);padding-top:12px}.wf-shop-totals>div{display:flex;justify-content:space-between;gap:20px;padding:7px 0;font-variant-numeric:tabular-nums}.wf-shop-totals>div:last-child{font-size:21px;font-weight:800;padding-top:16px;border-top:1px solid var(--shop-border);margin-top:6px}.wf-shop-help{font-size:13px;color:var(--shop-muted);line-height:1.5}.wf-shop-empty{padding:32px 0;color:var(--shop-muted)}
.wf-shop-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;max-width:800px}.wf-shop-field{display:flex;flex-direction:column;gap:7px;font-size:13px;color:var(--shop-muted)}.wf-shop-field input,.wf-shop-field select,.wf-shop-field textarea{width:100%;min-height:44px;border:1px solid var(--shop-border);border-radius:8px;background:var(--shop-surface);color:var(--shop-text);font:inherit;font-size:15px;padding:10px 12px}.wf-shop-field:has(textarea),.wf-shop-form>.wf-shop-btn,.wf-shop-form>.wf-shop-error{grid-column:1/-1}.wf-shop-field textarea{min-height:96px;resize:vertical}.wf-shop-address{grid-column:1/-1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.wf-shop-form>.wf-shop-btn{justify-self:start}.wf-shop-error{color:#a12626;font-size:14px;margin:0}.wf-shop-error:empty{display:none}.wf-shop-preview{background:#fff8ea;border:1px solid #f0d49e;color:#694711;padding:12px 16px;border-radius:8px;font-size:14px;line-height:1.5}.wf-shop-review{max-width:900px}.wf-shop-notice{position:fixed;z-index:10000;bottom:24px;left:50%;transform:translateX(-50%);max-width:calc(100% - 32px);background:#23312a;color:#fff;border-radius:10px;padding:13px 20px;box-shadow:0 4px 20px #0002;font:14px/1.5 system-ui}.wf-shop-notice:empty{display:none}.wf-shop-notice[data-error=true]{background:#852e2e}
.wf-shop-protection{grid-column:1/-1;min-width:0;max-width:100%}.wf-shop-protection__widget{min-height:65px;max-width:100%;overflow:auto}.wf-shop-protection .wf-shop-help{margin:8px 0 0}.wf-shop-protection .wf-shop-link{padding-left:0}
@media(max-width:700px){.wf-shop{padding:24px 16px 48px}.wf-shop-line{gap:12px;flex-wrap:wrap}.wf-shop-line img{width:65px;height:65px}.wf-shop-line__controls{width:100%;justify-content:flex-start;padding-left:77px}.wf-shop-line__controls strong{margin-left:auto}.wf-shop-form,.wf-shop-address{grid-template-columns:1fr}.wf-shop-form>.wf-shop-btn{width:100%}.wf-shop-shell a{padding:7px}.wf-shop-shell [data-wf-cart-label]{display:none}.wf-shop-actions{padding:10px}.wf-shop-actions .wf-shop-btn{min-width:120px}.wf-shop-notice{bottom:16px;width:max-content}}
@media(prefers-reduced-motion:reduce){.wf-shop-btn,.wf-shop-heart,.wf-shop-link{transition:none}}
.wf-shop-steps{display:flex;gap:8px;margin-bottom:24px;flex-wrap:wrap}.wf-shop-step{font:inherit;text-align:left;border:1px solid var(--shop-border);background:var(--shop-surface);color:var(--shop-muted);padding:12px 16px;border-radius:8px;cursor:pointer;flex:1;min-width:160px}.wf-shop-step[aria-current=step]{color:var(--shop-text);border-color:var(--shop-accent);font-weight:700}.wf-shop-step:disabled{cursor:default;opacity:.6}.wf-shop-step:focus-visible{outline:2px solid var(--shop-accent);outline-offset:3px}.wf-shop-step-panel{grid-column:1/-1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;min-width:0}.wf-shop-step-panel>h2,.wf-shop-step-panel>.wf-shop-help,.wf-shop-step-panel>.wf-shop-link{grid-column:1/-1}.wf-shop-step-panel>h2{margin:0 0 8px}.wf-shop-step-actions{grid-column:1/-1;display:flex;align-items:center;gap:16px;justify-content:space-between}.wf-shop-step-actions>.wf-shop-btn{margin-left:auto}.wf-shop-confirmation-details{padding:12px 0;border-top:1px solid var(--shop-border);font-size:14px}.wf-shop-confirmation-details p{margin:6px 0}
@media(max-width:700px){.wf-shop-step{min-width:0;flex-basis:100%;padding:10px 12px}.wf-shop-step-panel{grid-template-columns:1fr}.wf-shop-step-actions{gap:8px}.wf-shop-step-actions>.wf-shop-btn{flex:1}}

.wf-shop-protection--quiet .wf-shop-protection__widget{min-height:0}.wf-shop-form[data-inquiry=true] .wf-shop-step-actions>.wf-shop-btn{margin-left:0}

/* Country picker shares the public site's form palette and input geometry. */
.wf-shop-field input::placeholder,.wf-shop-field textarea::placeholder{color:var(--wf-color-placeholder,var(--shop-muted));opacity:.8;font-weight:400;font-size:.94em}
.wf-shop-field .iti{width:100%;min-width:0;--iti-border-color:var(--shop-border);--iti-country-selector-bg:var(--shop-surface);--iti-icon-color:var(--shop-muted);--iti-hover-color:var(--wf-color-secondary,#f4f5f6);--iti-spacer-horizontal:12px}
.wf-shop-field .iti__selected-country{border-radius:8px 0 0 8px;font:inherit;color:var(--shop-text);min-height:44px}
.wf-shop-field .iti__selected-country:focus-visible{outline:2px solid var(--shop-accent);outline-offset:3px}
.wf-shop-field .iti__country-selector{z-index:20;font-size:14px;max-width:calc(100vw - 32px);color:var(--shop-text)}
.wf-shop-field .iti__search-input{padding-left:32px;font-size:14px}
.wf-shop-field>.wf-shop-help:empty{display:none}.wf-shop-field>.wf-shop-help{margin:0}.wf-shop-field>.wf-shop-link{align-self:flex-start;padding:0;min-height:32px;text-align:left}
.wf-shop-btn[aria-busy="true"]::after,.wf-shop-heart[aria-busy="true"]::after{content:"";display:inline-block;flex:none;width:1em;height:1em;margin-inline-start:.5em;border:2px solid currentColor;border-inline-end-color:transparent;border-radius:50%;animation:wf-shop-pending .8s linear infinite}
.wf-shop-heart[aria-busy="true"] svg{display:none}
@keyframes wf-shop-pending{to{transform:rotate(360deg)}}
@media(prefers-reduced-motion:reduce){.wf-shop-btn[aria-busy="true"]::after,.wf-shop-heart[aria-busy="true"]::after{animation:none}}
.wf-detail[data-variant-display="Lista"][data-has-variants="true"] .wf-detail__price,.wf-detail[data-variant-display="Lista"][data-has-variants="true"] .wf-detail__stock,.wf-detail[data-variant-display="Lista"][data-has-variants="true"] .wf-detail__regular-price,.wf-detail[data-variant-display="Lista"][data-has-variants="true"] .wf-detail__discount{display:none}
.wf-catalog .wf-shop-actions[hidden]{display:none}
/* A corner favorite does not reserve a purchase footer in grid cards. */
.wf-catalog[data-layout="grid"][data-list-cart-enabled="false"] .wf-shop-actions,
.wf-catalog[data-layout="grid"] .wf-shop-actions[data-wf-list-cart="false"],
.wf-catalog[data-layout="grid"] .wf-shop-actions:empty{min-height:0;padding:0;border:0}
.wf-variants{margin:2rem 0;min-width:0;color:var(--wf-text,var(--wf-color-text))}
.wf-variants h2{font-size:1.3rem;line-height:1.3;margin:0 0 1rem}
.wf-variants__row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:.75rem 1rem;padding:1rem 0;border-top:1px solid var(--wf-border,var(--wf-color-border))}
.wf-variants__info{min-width:0;overflow-wrap:anywhere}.wf-variants__info h3{font-size:1rem;line-height:1.4;margin:0 0 .35rem}
.wf-variants__info .wf-shop-help{margin:.3rem 0 0}.wf-variants__price{font-variant-numeric:tabular-nums}
.wf-variants__controls{display:flex;align-items:center;gap:.5rem;min-width:0}.wf-variants__controls .wf-shop-qty{width:76px;min-height:44px}.wf-variants__controls .wf-shop-btn{min-height:44px}
.wf-variants__status{grid-column:1/-1;margin:0;font-size:.9rem}.wf-variants__status:empty{display:none}
@media(max-width:600px){.wf-variants__row{grid-template-columns:minmax(0,1fr)}.wf-variants__controls .wf-shop-btn{flex:1;min-width:0}}

.wf-shop:has([data-wf-shared-commerce-account]){width:100%;max-width:560px;padding:clamp(24px,5vw,48px) max(20px,env(safe-area-inset-left)) 56px}
[data-wf-shared-commerce-account]{width:100%;min-width:0}
.wf-shop-shell a{position:relative;min-width:44px;min-height:44px;justify-content:center}
.wf-shop-shell [data-wf-cart-link] svg{width:24px;height:24px}
.wf-shop-shell :is([data-wf-cart-count],[data-wf-favorite-count]){position:absolute;top:0;right:0;min-width:17px;line-height:17px;font-size:10px}
.wf-orders__list,.wf-orders__items{display:grid;gap:12px;margin:20px 0}
.wf-orders__row,.wf-orders__items article{display:grid;gap:8px;text-align:left;width:100%;padding:18px;border:1px solid var(--shop-border);border-radius:12px;background:var(--shop-surface);color:var(--shop-text);font:inherit;overflow-wrap:anywhere}
.wf-orders__row{cursor:pointer;grid-template-columns:minmax(0,1fr) auto}.wf-orders__row span:first-of-type{grid-column:1;font-size:.9rem;color:var(--shop-muted)}.wf-orders__row span:last-child{grid-column:2;grid-row:1/3;align-self:center;font-weight:700}
@media(max-width:420px){.wf-orders__row{grid-template-columns:minmax(0,1fr)}.wf-orders__row span:last-child{grid-column:1;grid-row:auto}}

/* Stable shared loading and checkout geometry on every site. */
.wf-shop-loading{min-height:260px}.wf-shop-loading__rows{display:grid;gap:16px;margin-top:20px}.wf-shop-loading__row{height:88px;border-radius:12px;border:1px solid var(--shop-border);background:linear-gradient(100deg,var(--shop-surface) 25%,var(--wf-color-secondary,#f4f5f6) 45%,var(--shop-surface) 65%);background-size:220% 100%;animation:wf-shop-loading 1.6s linear infinite}
@keyframes wf-shop-loading{to{background-position:-220% 0}}
.wf-shop-address>.wf-shop-help{grid-column:1/-1;margin:0}.wf-shop-new-address{justify-self:start;min-height:44px;padding:8px 12px;border:1px solid var(--shop-border);border-radius:8px;text-decoration:none}
.wf-shop-step-panel{align-content:start}.wf-shop-step-panel>[hidden]{display:none}.wf-shop-step-actions{padding-top:6px}
.wf-shop-line>a:not(:has(img)),.wf-shop-line>span{min-width:0;overflow-wrap:anywhere}.wf-shop-line>a:not(:has(img)){flex:1}.wf-shop-line>img{flex:none}.wf-shop-line>.wf-shop-link{flex:none;min-height:44px}
@media(max-width:700px){.wf-shop-step-panel{gap:16px}.wf-shop-step-actions{flex-wrap:wrap}.wf-shop-step-actions>.wf-shop-btn{min-height:48px}.wf-shop-new-address{width:100%}.wf-shop-line__controls{padding-left:0;gap:10px}.wf-shop-line__controls .wf-shop-link{min-height:44px}.wf-shop-line__controls strong{min-width:0}.wf-shop-loading__row{height:110px}}
@media(prefers-reduced-motion:reduce){.wf-shop-loading__row{animation:none}}

